@import "@fontsource-variable/host-grotesk";
@import "@fontsource-variable/source-code-pro";

/* Light (faithful): white paper, #232323 ink (text, 1px grid lines, dark tiles, filled
   buttons), mint #a1ffcb as the single accent, #d9d9d9 / #e0e0e0 quiet tiles and 65% ink for
   mono captions. The client tiles' deep blues are the chart colours. Square corners. */
:root {
  --background: oklch(1 0 0);
  --foreground: oklch(0.256 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.256 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.256 0 0);
  --primary: oklch(0.256 0 0);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.907 0 0);
  --secondary-foreground: oklch(0.256 0 0);
  --muted: oklch(0.885 0 0);
  --muted-foreground: oklch(0.256 0 0 / 65%);
  --accent: oklch(0.927 0.115 159);
  --accent-foreground: oklch(0.256 0 0);
  --destructive: oklch(0.577 0.215 27);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.256 0 0);
  --input: oklch(0.256 0 0);
  --ring: oklch(0.256 0 0);
  --highlight: oklch(0.927 0.115 159);
  --highlight-foreground: oklch(0.256 0 0);
  --glow: oklch(0.927 0.115 159);
  --chart-1: oklch(0.274 0.106 263);
  --chart-2: oklch(0.408 0.119 251);
  --chart-3: oklch(0.626 0.107 205);
  --chart-4: oklch(0.296 0.108 281);
  --chart-5: oklch(0.447 0.109 244);
  --sidebar: oklch(1 0 0);
  --sidebar-foreground: oklch(0.256 0 0);
  --sidebar-primary: oklch(0.256 0 0);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.927 0.115 159);
  --sidebar-accent-foreground: oklch(0.256 0 0);
  --sidebar-border: oklch(0.256 0 0);
  --sidebar-ring: oklch(0.256 0 0);

  --typeface-body: "Host Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Host Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "Source Code Pro Variable", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0rem;
  --page-width: 90rem;
  --page-gutter: 1.25rem;
  --section-y: 5rem;
}

/* Dark: the wall inverted. A near-black #181818 paper, white text and grid lines, #232323
   and #2e2e2e quiet tiles, the same mint accent. */
.dark {
  --background: oklch(0.209 0 0);
  --foreground: oklch(0.985 0 0);
  --card: oklch(0.256 0 0);
  --card-foreground: oklch(0.985 0 0);
  --popover: oklch(0.256 0 0);
  --popover-foreground: oklch(0.985 0 0);
  --primary: oklch(0.985 0 0);
  --primary-foreground: oklch(0.209 0 0);
  --secondary: oklch(0.3 0 0);
  --secondary-foreground: oklch(0.985 0 0);
  --muted: oklch(0.32 0 0);
  --muted-foreground: oklch(0.985 0 0 / 65%);
  --accent: oklch(0.927 0.115 159);
  --accent-foreground: oklch(0.256 0 0);
  --destructive: oklch(0.68 0.19 25);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.985 0 0 / 85%);
  --input: oklch(0.985 0 0 / 85%);
  --ring: oklch(0.985 0 0);
  --highlight: oklch(0.927 0.115 159);
  --highlight-foreground: oklch(0.256 0 0);
  --glow: oklch(0.927 0.115 159);
  --chart-1: oklch(0.42 0.12 263);
  --chart-2: oklch(0.5 0.12 251);
  --chart-3: oklch(0.626 0.107 205);
  --chart-4: oklch(0.42 0.12 281);
  --chart-5: oklch(0.52 0.11 244);
  --sidebar: oklch(0.209 0 0);
  --sidebar-foreground: oklch(0.985 0 0);
  --sidebar-primary: oklch(0.985 0 0);
  --sidebar-primary-foreground: oklch(0.209 0 0);
  --sidebar-accent: oklch(0.927 0.115 159);
  --sidebar-accent-foreground: oklch(0.256 0 0);
  --sidebar-border: oklch(0.985 0 0 / 85%);
  --sidebar-ring: oklch(0.985 0 0);
}
